import{_ as e,o as a,c as s,ah as t}from"./chunks/framework.ojwJKwrc.js";const k=JSON.parse('{"title":"Heliodor Linux ベンチマーク","description":"","frontmatter":{},"headers":[],"relativePath":"ja/benchmarks/heliodor.md","filePath":"ja/benchmarks/heliodor.md"}'),l={name:"ja/benchmarks/heliodor.md"};function n(d,i,h,r,o,p){return a(),s("div",null,[...i[0]||(i[0]=[t(`<h1 id="heliodor-linux-ベンチマーク" tabindex="-1">Heliodor Linux ベンチマーク <a class="header-anchor" href="#heliodor-linux-ベンチマーク" aria-label="Permalink to &quot;Heliodor Linux ベンチマーク&quot;">​</a></h1><p>Heliodor は Celox の大規模な外部 Veryl ワークロードです。固定した Linux イメージを 起動し、同じ設計リビジョンと入力を使って Celox のネイティブバックエンド、tiered JIT、 Veryl-CC の同期版と tiered 版を CPU アーキテクチャごとに比較します。 Celox の tiered 版はインタプリタで実行を始め、バックグラウンドでネイティブコードを生成します。 Veryl-CC の tiered 版は Cranelift で実行を始め、C の非同期コンパイルが完了すると切り替えます。 これは通常の <code>veryl test --backend cc</code> と同じ <code>aot_c_async=true</code> の設定です。 同期版は明示的に <code>aot_c_async=false</code> とし、C のコンパイル完了を待ってから実行します。 Cranelift 単独の Linux 起動時間はこの比較の有効な尺度を大幅に 超えるため、計測・公開しません。</p><h2 id="測定するもの" tabindex="-1">測定するもの <a class="header-anchor" href="#測定するもの" aria-label="Permalink to &quot;測定するもの&quot;">​</a></h2><p>次の 3 つを分けて計測します。</p><ol><li>同期バックエンドが設計をコンパイルする時間。</li><li>テストベンチを含め、ワークロード全体を実行する時間。</li><li>コンパイルとシミュレーションを並行させる tiered 実行の起動から Linux 完了までの時間。</li></ol><p>実行時間は両シミュレータともテストベンチの処理を含みます。tiered 版は「実行開始まで」「コンパイルと 並行した実行」「Linux 起動完了までの総時間」を別のグラフで表示します。tiered の実行区間には 切り替え前のバックエンドも含まれるため、生成コードだけの速度としては比較しません。 Veryl-CC は C のコンパイル完了前に Cranelift だけで処理を終える場合もあり、 その場合も有効な tiered の測定値として扱います。 起動時間と総時間は設計の解析前から測り、ソースファイルの読み込みと Cargo によるランナーの ビルド時間は含みません。TSV の <code>compile_elapsed_ns</code> は tiered 版では実行開始までの時間を表し、 バックグラウンドのコンパイル全体の時間ではありません。Veryl-CC の同期版・tiered 版はそれぞれ 独立した空の AOT-C キャッシュを使います。過去の同期版の測定値は同じ系列に保持します。</p><p>途中までの起動、完了時間の推定、コンパイルだけの結果は、実行成功として扱いません。</p><h2 id="有効な結果" tabindex="-1">有効な結果 <a class="header-anchor" href="#有効な結果" aria-label="Permalink to &quot;有効な結果&quot;">​</a></h2><p>次の条件をすべて満たす実行だけを採用します。</p><ul><li>固定した Heliodor とワークロードのリビジョンを使う。</li><li>設定された Linux 完了マーカーまで到達する。</li><li>コンパイル時間と実行時間を分けて記録する。</li><li>意図した Celox / Veryl リビジョンからランナーをビルドする。</li><li>タイムアウトや意味上の不一致を調査できるログを残す。</li><li>Celox の tiered 実行が Linux 完了前に生成コードへ昇格し、生成コードで 1 回以上評価したことを確認する。</li><li>Veryl-CC の tiered 実行で C の非同期コンパイルが有効であり、生成コードかフォールバックで 1 回以上実行したことを確認する。</li></ul><p>完了マーカーを固定することで、高速に失敗した実行や未完了の起動を性能向上として 誤って報告することを防ぎます。</p><h2 id="ローカル実行" tabindex="-1">ローカル実行 <a class="header-anchor" href="#ローカル実行" aria-label="Permalink to &quot;ローカル実行&quot;">​</a></h2><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">bash</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> scripts/run-heliodor-bench.sh</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> run</span></span></code></pre></div><p>両方の tiered バックエンドを比較する場合:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">HELIODOR_RUNNERS</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;celox-tiered veryl-cc-tiered&quot;</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> bash</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> scripts/run-heliodor-bench.sh</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> run</span></span></code></pre></div><p>CI の固定 <code>gate</code> は x86-64 で <code>veryl-cc-sync</code>、<code>celox</code>、<code>celox-tiered</code>、 <code>veryl-cc-tiered</code> を実行します。夜間の AArch64 ジョブも同じ 4 種類を測定し、 各アーキテクチャで両方の tiered 結果が揃った場合に公開します。</p><p>初回は固定した Heliodor checkout の取得にネットワークアクセスが必要です。スクリプトは 使用リビジョン、ビルド構成、完了状態、計測時間を表示します。変更前後の比較には同じ マシンと構成を使ってください。</p><p>公開結果は<a href="./">ベンチマークダッシュボード</a>の <strong>Heliodor Linux</strong> に掲載します。</p><h2 id="大規模・linux-バージョン別の測定" tabindex="-1">大規模・Linux バージョン別の測定 <a class="header-anchor" href="#大規模・linux-バージョン別の測定" aria-label="Permalink to &quot;大規模・Linux バージョン別の測定&quot;">​</a></h2><p>nightly とプロファイルを取らない手動実行では、次の 11 ケースを x86-64 （<code>ubuntu-24.04</code>）と AArch64（<code>ubuntu-24.04-arm</code>）で測定します。 各ケースで前述の 4 バックエンドを実行します。</p><table tabindex="0"><thead><tr><th>ゲスト Linux カーネル</th><th>hart 数</th></tr></thead><tbody><tr><td>5.15</td><td>1、2、4、8</td></tr><tr><td>6.6</td><td>1、2、4</td></tr><tr><td>7.1</td><td>1、2、4</td></tr><tr><td>7.1（ベクトル有効）</td><td>1</td></tr></tbody></table><p>Heliodor のリビジョンは <code>6285682fa0a514077da9d17fee385c7841160025</code> に固定します。 Linux バージョンはシミュレーション内で起動するゲストのもので、ホスト OS の違いではありません。 各実行のタイムアウトは 1 時間です。未完了・失敗は計測値として公開せず、 両アーキテクチャの全ケースが成功した場合に nightly の結果を公開します。</p><p>ダッシュボードにはカーネルと hart 数を区別して表示します。設計リビジョンが異なるため、 従来の固定 gate とは別の履歴です。コンパイル・実行・tiered の時間の定義は共通です。 大規模ケースは PR ごとには実行しません。</p><p>Linux 6.6 の 4 hart をローカルで実行する例:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">HELIODOR_REF</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">6285682fa0a514077da9d17fee385c7841160025</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> \\</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">HELIODOR_TESTS=test_soc_66_smp_linux_boot_4hart </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">\\</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">HELIODOR_RUNNERS=</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;veryl-cc-sync celox celox-tiered veryl-cc-tiered&quot;</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> \\</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">HELIODOR_CELOX_CARGO_PROFILE=release </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">HELIODOR_TIMEOUT_SEC=</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">3600</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> \\</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">bash </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">scripts/run-heliodor-bench.sh</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> run</span></span></code></pre></div>`,25)])])}const u=e(l,[["render",n]]);export{k as __pageData,u as default};
